public class FastDateFormat_format_TriageGen4Test {





    @Test
    public void testFormatWithLocale() {
        // Arrange
        String pattern = "MMMM";
        Locale locale = Locale.FRENCH;
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, locale);

        Calendar cal = Calendar.getInstance(Locale.FRENCH);
        cal.set(2023, Calendar.OCTOBER, 1);
