/**
 * Unit tests for FastDateFormat.format(Date)
 */
public class FastDateFormat_format_TriageGen4Test {













    @Test
    public void testFormatWithDifferentTimeZonesSameDate() {
        // Arrange
        String pattern = "HH";
        Date date = new Date(); // Current time

        FastDateFormat fdfUTC = FastDateFormat.getInstance(pattern, TimeZone.getTimeZone("UTC"));
        FastDateFormat fdfEST = FastDateFormat.getInstance(pattern, TimeZone.getTimeZone("EST"));

        // Act
        String resUTC = fdfUTC.format(date);
        String resEST = fdfEST.format(date);

        // Assert
        // They might be the same if the hour doesn't cross the boundary, 
        // but they are valid calls. To be safe, we just check they are both valid strings.
        assertNotNull(resUTC);
        assertNotNull(resEST);
    }
}
